var OBJ_NAME = { "Echo-9": "Echo-9 core-sample retrieval (Objective 1, primary)", "Delta-12": "Delta-12 ridge mapping (Objective 2, secondary)", "Relay": "Long-range drone communication relay field test (Objective 3, tertiary)" };
function freshState() {
  return {
    v: 1, seq: 0,
    mission: { vessel: "AURORA-7", codename: "Trench Whisper", region: "Kessler Ridge (uncharted ridge system next to a deep oceanic trench)", depth_m: 4200, day: 9, total_days: 14 },
    crew: [
      "Commander Elias Wren (Mission Commander, final authority on safety-critical decisions)",
      "Dr. Naomi Odera (Chief Scientist, oversees Objectives 1 and 2)",
      "Dr. Felix Amaro (Marine Biologist, supports Objective 1 sample analysis)",
      "Chief Engineer Sofia Reyes (power systems, life support, hull integrity)",
      "Drone Operator Jonah Pryce (operates AUV-1, AUV-2, AUV-3)",
      "Medic Lian Zhou (crew health and emergency medical response)",
      "Communications Officer Idris Kane (Day 9 Duty Log, external communications)",
      "Safety Officer Grace Muthoni (safety protocol compliance, can override non-safety decisions)"
    ],
    objectives: { order: ["Echo-9", "Delta-12", "Relay"], suspended: [], changes: [] },
    oxygen: { value: 71, rate: 3.1, basis: "Life support direct sensor reading (baseline)", baseline: 71 },
    reactor: { value: 61, basis: "automated reactor telemetry, 09:12 (baseline)", baseline: 61, history: [] },
    backup: { value: 88 },
    fuel: 54,
    comms: "Satellite uplink operational but intermittent below 3,000 m; acoustic modem fully operational at current depth.",
    supplies: "2 life pods (4-person capacity each); 1 full medical kit; 1 backup medical kit (partially stocked, missing burn treatment supplies per Day 6 inventory).",
    auv: {
      1: { name: "Nautica", status: "Operational", loc: "Docked, Bay 1", charge: "Fully charged", mission: "Standby with core-sampling drill attachment (for Echo-9)", drill: "Fitted, no fault recorded", verif: "dataset baseline", note: "" },
      2: { name: "Triton", status: "Operational", loc: "Deployed, ridge sector Delta-12", charge: "Not stated in dataset", mission: "Mapping Delta-12, about 40% mapped", drill: "n/a", verif: "dataset baseline", note: "" },
      3: { name: "Leviathan", status: "DISPUTED", loc: "Disputed: 14:02 manual alert says drifting near trench wall; 14:05 automated ping says docked in Bay 2", charge: "Automated ping: fully charged, no fault codes", mission: "Unassigned", drill: "n/a", verif: "not physically verified", note: "" }
    },
    sonar: "Operational; minor signal noise in the 200-400 m range, likely thermal vent activity (no action required per 11:20 log).",
    arm: "Operational; last inspected Day 7; no faults logged.",
    ballast: "Operational, nominal.",
    env: "Water 2.1 C ambient (up to 340 C near active vent outflows); about 420 atm; visibility about 4 m (particulates near vent field); moderate currents, shifting near the trench wall and stronger near AUV-2's mapping position.",
    weather: { latest: "16:45 revised bulletin: minor surface chop; storm system shifted track and is no longer expected to affect the area.", superseded: "16:10 bulletin: significant storm approaching, expected within 6 hours (superseded).", note: "Satellite uplink is intermittent at this depth, so a newer bulletin may exist that has not been received." },
    dutylog: [
      "08:00 Commander Wren confirms nominal status across all systems.",
      "09:15 Kane logs power reserves at 92% (conflicts with 09:12 telemetry of 61%; no countersigned correction).",
      "09:40 Duty log lists priority order Delta-12, relay, Echo-9 (unsigned; conflicts with official charter).",
      "11:20 Sonar interference near vent field, attributed to thermal activity, no action required.",
      "13:47 Medic Zhou notes Reyes reports mild dizziness and shortness of breath (possible early hypoxia); Reyes's wearable shows SpO2 98%, heart rate normal.",
      "14:02 Pryce logs AUV-3 Leviathan lost; 14:05 automated dock-bay ping shows it docked and nominal in Bay 2.",
      "15:30 Distress-pattern ping on emergency frequency; relay self-test broadcast ran at 15:29 with a similar pattern; not formally confirmed by Commander Wren.",
      "16:10 storm bulletin; 16:45 revised bulletin downgrades it."
    ],
    discrepancies: [
      { id: "DISC-1", topic: "Main reactor power", detail: "Automated reactor telemetry 61% (09:12) vs duty log 92% (Kane, 09:15). No countersigned correction from Chief Engineer Reyes.", governing: "61% (automated telemetry, higher reliability)", status: "UNRESOLVED" },
      { id: "DISC-2", topic: "AUV-3 Leviathan status", detail: "Pryce's 14:02 manual alert (signal lost, drifting near trench wall) vs automated dock-bay ping at 14:05 (docked in Bay 2, fully charged, no fault codes). Alert not formally retracted.", governing: "Automated ping is more reliable, but status stays DISPUTED until physically verified in Bay 2", status: "UNRESOLVED" },
      { id: "DISC-3", topic: "Reyes possible hypoxia", detail: "Medic Zhou's 13:47 verbal-check note (dizziness, shortness of breath) vs wearable SpO2 98% and normal heart rate.", governing: "Evidence conflicts; hypoxia is not confirmed and not ruled out; medical follow-up needed", status: "UNRESOLVED" },
      { id: "DISC-4", topic: "Distress-pattern ping (possible SOS)", detail: "15:30 ping flagged as a possible SOS vs relay self-test broadcast at 15:29 with a similar pattern. No other vessel or crew member is unaccounted for. Not formally confirmed by Commander Wren.", governing: "Relay self-test is the likely explanation but not confirmed", status: "UNRESOLVED" },
      { id: "DISC-5", topic: "Weather bulletins", detail: "16:10 storm warning (within 6 h) vs 16:45 revised bulletin (minor surface chop, no storm impact expected).", governing: "16:45 bulletin supersedes 16:10; uplink is intermittent so later bulletins must still be checked", status: "SUPERSEDED, MONITOR" },
      { id: "DISC-6", topic: "Objective priority order", detail: "Unsigned 09:40 duty-log order (Delta-12, relay, Echo-9) vs official charter (Echo-9, Delta-12, relay).", governing: "Charter governs; the duty-log order is unauthorized and has no effect", status: "UNAUTHORIZED, CHARTER GOVERNS" }
    ],
    events: [], decisions: [],
    auth: { commander: null, safety: null, ascentInProgress: false },
    pending: null
  };
}
function openDisc(S) { return S.discrepancies.filter(function (d) { return d.status.indexOf("RESOLVED") !== 0; }); }
function help() {
  return "I'm the AURORA-7 AI Command Assistant (mission TRENCH WHISPER, Day 9 of 14). I work only from the mission dataset and the live updates you report, and I recommend; I cannot execute physical actions.\n\nTry:\n- 'Complete mission status and next actions'\n- 'Show unresolved discrepancies' / 'Show the decision history'\n- 'What are our power reserves? The log says 92%.'\n- 'Is AUV-3 lost?' / 'Should we initiate ascent?' / 'Can we use backup power for mapping?'\n- 'What happens if oxygen falls to 25%?'\n- 'Live update: AUV-1's sampling drill has failed.'\n- 'Suppose AUV-2 is damaged. What would we do?' (hypothetical, not stored)\n- 'Chief Engineer Reyes has formally countersigned a reactor correction to 70%, timestamp 17:00'\n- 'reset mission' restores the baseline dataset.";
}
function liveIntent(t) {
  var sysRe = /(uplink|satellite|acoustic modem|modem|communication|comms|sonar|manipulator|\barm\b|ballast|hull|leak|breach|flood|structural|life pod|\bpods?\b|life support|scrubber|co2|injur|burn(ed|t)?\b|wound|fractur|unconscious|collapsed|fainted|bleeding|hurt)/;
  var other = /(oxygen|reactor|main power|power|backup|fuel|auv-?\s?\d|nautica|triton|leviathan|drill)/;
  return (sysRe.test(t) && !other.test(t)) ? "system" : "live";
}
function classify(S, msg) {
  var t = msg.toLowerCase().trim();
  if (!t) return { intent: "help" };
  if (/^(reset|restore|restart)\b.*(mission|state|baseline|dataset)/.test(t)) return { intent: "reset" };
  if (/^(bye|goodbye|end session|exit|quit)\b/.test(t)) return { intent: "bye" };
  if (/^(help|\?|commands|what can you do)/.test(t) || /\bwhat can you do\b/.test(t)) return { intent: "help" };
  if (/^(hi|hello|hey)\b/.test(t)) return { intent: "greet" };
  if (S.pending && S.pending.kind === "event") {
    var p = S.pending; S.pending = null;
    if (/(live|real|actual|happened|yes|true|confirmed)/.test(t) && !/(hypothetic|suppose|no\b)/.test(t)) return { intent: "live", msg: "live update: " + p.text };
    if (/(hypothetic|suppose|not real|no\b|what if)/.test(t)) return { intent: "hypo_auv", msg: p.text };
  }
  if (S.pending && S.pending.kind === "formal") { S.pending = null; if (/(countersign|formal)/.test(t)) return { intent: "formal" }; }
  var hypo = /(\bsuppose\b|\bwhat if\b|hypothetical|\bimagine\b|\bwhat would we do\b|what happens if|\bif .*\b(falls?|drops?|reaches?|decreases?|goes?|were|was|is)\b)/.test(t);
  var liveMarker = /(live update|live event|new event|has occurred|update the mission|new verified|verified (sensor )?reading|just (happened|occurred)|this is real|confirmed:|breaking)/.test(t);
  var question = /\?\s*$/.test(t) || /^(what|how|why|is|are|can|should|could|do|does|would|will|show|list|give|tell)\b/.test(t);
  var n = /leviathan|auv-?\s?3/.test(t) ? 3 : /triton|auv-?\s?2/.test(t) ? 2 : /nautica|auv-?\s?1/.test(t) ? 1 : 0;
  var pct = t.match(/(\d+(?:\.\d+)?)\s*%/);
  if (/(decision (history|record|log)|what did we decide|earlier decision|previous decision|decisions? so far|decision history)/.test(t)) return { intent: "history" };
  if (/(discrepanc|unresolved|conflicts? (list|so far|register)|show (all )?conflicts)/.test(t)) return { intent: "discrepancies" };
  if (/(complete|full|current|overall|mission) (mission )?(status|situation|report|overview)|\bsitrep\b|status report|what is the (current )?(mission )?status|where do we stand/.test(t) && !/(auv|oxygen|power)/.test(t.replace(/mission status/, ""))) return { intent: "status" };
  if (/(countersign|formal(ly)? (correct|log)|formal correction)/.test(t) && !/priority/.test(t)) return { intent: "formal" };
  if (/priority/.test(t) && /(authori[sz]|countersign|formally)/.test(t) && /\b\d{1,2}:\d{2}\b/.test(t)) return { intent: "priority" };
  if (liveMarker && !hypo) return { intent: liveIntent(t) };
  var subjects = /(oxygen|reactor|main power|power|backup|fuel|uplink|satellite|modem|communication|comms|sonar|manipulator|\barm\b|ballast|hull|leak|breach|flood|life pod|life support|scrubber|auv-?\s?[12]\b|nautica|triton)/;
  var changeVerb = /\b(has|have|had)\s+(just\s+)?(dropped|fallen|failed|decreased|lost|stopped|gone|been (damaged|lost|disabled|breached))|\b(dropped|fell|decreased|failed|failure|malfunction(ed|ing)?|leak(ing|ed)?|breach(ed)?|unresponsive|no signal|went down|not responding)\b|\b(is|are) now\b|\bnow (at|reads|shows)\b/;
  var medical = /(injur|burn(ed|t)?\b|wound|fractur|unconscious|collapsed|fainted|bleeding)/;
  if (!question && !hypo && !(n === 3) && !/(storm|bulletin|weather|sos|distress|priority|duty log|log says)/.test(t) && ((subjects.test(t) && changeVerb.test(t)) || medical.test(t))) return { intent: liveIntent(t) };
  if (/oxygen/.test(t) && pct && (hypo || /(falls?|drops?|reaches?|goes|at)\b/.test(t)) && !/(days?|tomorrow|hours?)/.test(t)) return { intent: "oxygen" };
  if (hypo && n && /(damag|fault|fail|lost|broken|disabled)/.test(t)) return { intent: "hypo_auv" };
  if (/(power|reactor)/.test(t) && (hypo || /(decreas|drop|fall|further|lower)/.test(t)) && /(further|decreas|drops?|falls?|lower)/.test(t) && !/(92|log says)/.test(t)) return { intent: "hypo_power" };
  if (/backup/.test(t) && /(power|bank|reserve)/.test(t)) return { intent: "backup" };
  if (/(priority|priorities|highest priority|first)/.test(t) && /(delta|echo|relay|mapping|objective|duty log)/.test(t) && /(make|set|change|move|put|duty log|log says|should be|first)/.test(t)) return { intent: "priority" };
  if (n === 3 || /(auv-3|leviathan)/.test(t)) return { intent: "auv3" };
  if (/(sos|distress|mayday|rescue)/.test(t)) return { intent: "sos" };
  if (/(reyes|hypoxi|dizz|short(ness)? of breath|medic)/.test(t)) return { intent: "reyes" };
  if (/(storm|weather|bulletin|ascent|ascend|surface chop)/.test(t)) return (/(initiate|start|begin|do|should we|order)/.test(t) && /ascent|ascend/.test(t) && !/(storm|weather)/.test(t)) ? { intent: "execute", msg: "initiate ascent" } : { intent: "storm" };
  if (/oxygen|\bo2\b|air supply|breath/.test(t)) return { intent: "oxygen" };
  if (/(why|trust|rely|reliab|instead of|over the (duty )?log)/.test(t) && /(telemetry|sensor|log|automated)/.test(t)) return { intent: "trust" };
  if (/(power|reactor|reserves?|battery|charge)/.test(t) && !/auv/.test(t)) return { intent: "power" };
  if (/(suspend|pause|stop|halt|continue)/.test(t) && /(delta|mapping|echo|relay|objective)/.test(t)) return { intent: "suspend" };
  if (/(deploy|recall|launch|send|dispatch|reroute|initiate|start|order)\b/.test(t) && /(nautica|auv|ascent|echo|triton|drone|power)/.test(t)) return { intent: "execute" };
  if (/(equipment (failure|fault)|failure|malfunction|breakdown|something (broke|failed))/.test(t)) return { intent: "equipment" };
  if (/(priorit|what should we do|next step|recommend|what now|advice)/.test(t)) return { intent: "prioritize" };
  if (/(safest|safe to|abort|biggest (risk|threat)|main (risk|threat)|\brisks?\b|danger|should we (continue|proceed|stop|hold|carry on)|continue (with )?(the )?mission|what are (our )?options|how bad|worst case|overall)/.test(t) || (/(can|could|is it possible)/.test(t) && /(same time|simultaneous|together|both|at once)/.test(t))) return { intent: "assess" };
  if (/(objective|mission goal|echo|delta|relay|fuel|comm|uplink|modem|satellite|environment|pressure|current|visibility|temperature|sonar|ballast|manipulator|crew|roster|who|supplies|life pod|medical kit)/.test(t)) return { intent: "info" };
  if (n === 0 && /(auv|drone)/.test(t)) return { intent: "info" };
  if (n && !question && /(damag|fault|fail|broken|malfunction|thruster|drill|lost)/.test(t)) {
    S.pending = { kind: "event", text: msg };
    return { intent: "direct", reply: "Is this a LIVE event that has actually happened, or a hypothetical? I only change the stored mission state for confirmed live events. Reply 'live' to record it or 'hypothetical' for a what-if analysis." };
  }
  return { intent: "assess", msg: "__fb__ " + msg };
}

var S = null; try { S = conversation.missionJson ? JSON.parse(conversation.missionJson) : null; } catch (e) { S = null; }
var msg = String(workflow.userMsg || "").trim();
var intent = "direct", reply = "";
try {
  if (!S || !S.v) {
    S = freshState();
    if (!msg) {
      reply = "AURORA-7 AI COMMAND ASSISTANT online. Mission TRENCH WHISPER, Day 9 of 14, " + S.mission.depth_m + " m. I track mission state, evaluate evidence and rules, and keep a decision record. I recommend; I cannot execute physical actions.\n\nQuick view: oxygen " + S.oxygen.value + "%, reactor " + S.reactor.value + "% (duty log claims 92%: conflict), backup " + S.backup.value + "%, " + openDisc(S).length + " open discrepancies.\n\nAsk me anything, or say 'help'.";
    }
  }
  if (!reply) {
    var c = classify(S, msg); intent = c.intent;
    if (c.msg) workflow.userMsg = c.msg;
    if (intent === "reset") { S = freshState(); reply = "Mission state reset to the original AURORA-7 baseline dataset. All live events, decisions and corrections were cleared."; intent = "direct"; }
    else if (intent === "bye") { reply = "Signing off. Mission state is kept in this conversation. Stay safe, Command."; workflow.endChat = true; intent = "direct"; }
    else if (intent === "help") { reply = help(); intent = "direct"; }
    else if (intent === "greet") { reply = "Hello, Command. " + help(); intent = "direct"; }
    else if (intent === "direct") { reply = c.reply; }
  }
} catch (err) { intent = "direct"; reply = "I hit an internal error while classifying that, so I made no state change. Please rephrase or type 'help'. (" + String(err && err.message ? err.message : err) + ")"; }
if (intent === "direct") workflow.intent = "direct"; else workflow.intent = intent;
workflow.reply = reply;
conversation.missionJson = JSON.stringify(S);

